package org.schoolkernel.workspace;

import static org.junit.jupiter.api.Assertions.*;
import java.util.List;
import com.microsoft.playwright.APIResponse;
import com.microsoft.playwright.options.RequestOptions;
import org.junit.jupiter.api.Test;
import tools.jackson.databind.JsonNode;
import tools.jackson.databind.node.ObjectNode;

class DefinitionCatalogBrowserIT extends WorkbenchBrowserSupport {
    @Test void allCatalogCrossingsExactCompensationsExplicitWinsAndSourceFidelity(){
        for(int catalog=1;catalog<=8;catalog++){
            initial(catalog);open();ObjectNode document=((ObjectNode)storedWorkspaceDocument()).deepCopy(),def=document.withObject("definitionDraft").withObject("definition");
            if(catalog>=2)def.withArray("softConstraintOverrides").addObject().put("constraintId","soft.cohort-gap").put("weight",6);
            if(catalog>=3)def.withArray("softConstraintOverrides").addObject().put("constraintId","soft.cohort-late-start").put("weight",0);
            if(catalog>=5)((ObjectNode)def.path("cohorts").get(0)).put("maxDailyGaps",2);
            store("DEFINITION_DRAFT",document);JsonNode before=definition().deepCopy(),source=draft().path("sourceDocument").deepCopy();String unchanged=storedDocument();JsonNode preview=preview();assertEquals(unchanged,storedDocument());assertEquals(catalog,preview.path("sourceCatalog").intValue());assertEquals(9,preview.path("targetCatalog").intValue());assertTrue(preview.path("available").booleanValue());assertEquals(9-catalog,preview.path("newlyEnabledSettings").size());assertEquals(200,save(preview,null).status());
            ObjectNode expected=((ObjectNode)before).deepCopy().put("catalogVersion",9);if(catalog<2){expected.withArray("softConstraintOverrides").addObject().put("constraintId","soft.cohort-gap").put("weight",0);expected.withArray("softConstraintOverrides").addObject().put("constraintId","soft.cohort-week-balance").put("weight",0);}if(catalog<3)expected.withArray("softConstraintOverrides").addObject().put("constraintId","soft.cohort-late-start").put("weight",0);if(catalog<5)((ObjectNode)expected.path("cohorts").get(0)).put("maxDailyGaps",2147483647);assertEquals(expected,definition());assertEquals(source,draft().path("sourceDocument"));assertEquals(source.path("initialDefinition"),storedWorkspaceDocument().path("initialDefinition"));assertFalse(draft().path("issues").toString().contains("BLOCKING"));assertEquals(preview.path("adjustments"),draft().path("catalogUpgrades").get(0).path("adjustments"));
        }
    }
    @Test void browserCancelUnavailableHandoffExplicitNewDefaultReviewAndRestart(){
        initial(1);open();nav("Room policies");workbench.awaitText("require scheduling catalog 9");page().getByText("Review catalog upgrade",new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).click();page().locator("#preview-catalog-upgrade").waitFor();String before=storedDocument();page().locator("#preview-catalog-upgrade").click();page().locator("#catalog-upgrade-dialog").waitFor();workbench.awaitText("Class cohort-7a: maxDailyGaps = No limit");assertEquals(before,storedDocument());page().locator("#cancel-catalog-upgrade").click();assertEquals(before,storedDocument());page().locator("#preview-catalog-upgrade").click();page().locator("#confirm-catalog-upgrade").click();workbench.awaitText("Catalog 9 is already enabled");assertEquals(9,definition().path("catalogVersion").intValue());nav("Review");workbench.awaitText("Catalog upgrade 1 → 9");nav("Preferences");page().getByText("Edit preference: soft.cohort-gap",new com.microsoft.playwright.Page.GetByTextOptions().setExact(true)).click();assertEquals("value",page().locator("#preference-mode").inputValue());page().locator("#preference-mode").selectOption("default");page().locator("#save-preference").click();workbench.expect("document.querySelector('#school-save-status')?.textContent.startsWith('Saved —')");assertEquals(3,definition().path("softConstraintOverrides").size());assertEquals(2147483647,definition().path("cohorts").get(0).path("maxDailyGaps").intValue());String saved=storedDocument();workbench.reload();nav("School");workbench.awaitText("Catalog 9 is already enabled");assertEquals(saved,storedDocument());try(var restarted=startRestartableWorkspace()){workbench.open(((org.springframework.boot.web.server.context.WebServerApplicationContext)restarted).getWebServer().getPort());nav("School");workbench.awaitText("Catalog 9 is already enabled");assertEquals(saved,storedDocument());}
    }
    @Test void staleTokensUnsupportedLatestStatesCsrfAndAcceptedCurrent(){
        initial(1);open();JsonNode old=preview();String before=storedDocument();for(String target:List.of("0","1","8","10","4294967305","9.0","\"9\"")){assertEquals(409,command("catalog/preview",JSON.readTree("{\"targetCatalog\":"+target+"}"),null).status());assertEquals(before,storedDocument());}
        JsonNode csrf=JSON.readTree(page().request().get(base()+"/api/csrf").text());assertEquals(403,page().request().post(base()+"/api/definition-draft/catalog",RequestOptions.create().setData("{}").setHeader("Content-Type","application/json").setHeader("Origin",base()).setHeader("If-Match","\"ws-"+storedVersion()+"\"")).status());assertEquals(before,storedDocument());
        assertEquals(200,command("preferences",JSON.readTree("{\"constraintId\":\"soft.teacher-gap\",\"mode\":\"value\",\"weight\":4}"),null).status());before=storedDocument();assertEquals(409,save(old,null).status());assertEquals(before,storedDocument());assertEquals(412,save(old,"\"ws-1\"").status());assertEquals(before,storedDocument());assertEquals(200,save(preview(),null).status());before=storedDocument();JsonNode latest=preview();assertFalse(latest.path("available").booleanValue());assertEquals(409,save(latest,null).status());assertEquals(before,storedDocument());
        storeAccepted(fixtures.validAcceptedDocument());workbench.reload();open();assertEquals(8,definition().path("catalogVersion").intValue());JsonNode source=draft().path("sourceDocument").deepCopy();assertEquals(200,save(preview(),null).status());assertEquals(source,draft().path("sourceDocument"));for(var entry:source.properties())assertEquals(entry.getValue(),storedWorkspaceDocument().path(entry.getKey()));assertTrue(draft().path("catalogUpgrades").get(0).path("adjustments").isEmpty());
        for(WorkspaceState state:WorkspaceState.values())if(state!=WorkspaceState.DEFINITION_DRAFT){store(state.name(),storedWorkspaceDocument());before=storedDocument();assertEquals(409,command("catalog/preview",request(),null).status());assertEquals(before,storedDocument());assertEquals(409,save(old,null).status());assertEquals(before,storedDocument());}
    }
    @Test void browserUnsavedGuardNarrowStaleStorageTransportFreshReview() throws Exception {
        initial(1);open();nav("School");page().locator("#school-display-name").fill("Working name");page().locator("#preview-catalog-upgrade").click();page().locator("#school-stay").click();assertEquals(0,page().locator("#catalog-upgrade-dialog").count());page().locator("#preview-catalog-upgrade").click();page().locator("#school-discard-working").click();page().locator("#catalog-upgrade-dialog").waitFor();String before=storedDocument();for(int width:List.of(390,700)){workbench.viewport(width,844);workbench.expect("!document.querySelector('#catalog-upgrade-dialog') && !document.querySelector('#preview-catalog-upgrade')");workbench.expect("document.documentElement.scrollWidth <= innerWidth");assertEquals(before,storedDocument());}workbench.viewport(1280,800);page().locator("#preview-catalog-upgrade").click();page().locator("#catalog-upgrade-dialog").waitFor();assertEquals(200,command("preferences",JSON.readTree("{\"constraintId\":\"soft.teacher-gap\",\"mode\":\"value\",\"weight\":4}"),null).status());before=storedDocument();page().locator("#confirm-catalog-upgrade").click();workbench.awaitText("No portion of the upgrade was committed");assertEquals(before,storedDocument());assertTrue(page().locator("#confirm-catalog-upgrade").isDisabled());page().locator("#refresh-catalog-preview").click();workbench.expect("document.querySelector('#confirm-catalog-upgrade') && !document.querySelector('#confirm-catalog-upgrade').disabled");String stable=storedDocument();withRejectedWorkspaceUpdates("NEW.lifecycle_state = 'DEFINITION_DRAFT'",()->{page().locator("#confirm-catalog-upgrade").click();workbench.awaitText("No portion of the upgrade was committed");assertEquals(stable,storedDocument());});page().locator("#refresh-catalog-preview").click();workbench.expect("document.querySelector('#confirm-catalog-upgrade') && !document.querySelector('#confirm-catalog-upgrade').disabled");page().route("**/api/definition-draft/catalog",route->route.abort());page().locator("#confirm-catalog-upgrade").click();workbench.awaitText("No portion of the upgrade was committed");assertEquals(stable,storedDocument());page().screenshot(new com.microsoft.playwright.Page.ScreenshotOptions().setPath(java.nio.file.Path.of("/tmp/uc12-transport-dialog.png")));assertTrue(page().locator("#catalog-upgrade-dialog").isVisible());assertTrue(page().locator("#refresh-catalog-preview").isVisible());page().unroute("**/api/definition-draft/catalog");page().locator("#refresh-catalog-preview").click();workbench.expect("document.querySelector('#confirm-catalog-upgrade') && !document.querySelector('#confirm-catalog-upgrade').disabled");page().locator("#confirm-catalog-upgrade").click();workbench.awaitText("Catalog 9 is already enabled");assertEquals(4,definition().path("softConstraintOverrides").get(0).path("weight").intValue());assertEquals(2147483647,definition().path("cohorts").get(0).path("maxDailyGaps").intValue());
    }
    private void initial(int catalog){ObjectNode def=((ObjectNode)fixtures.validAcceptedDocument().path("acceptedBaseline").path("definition")).deepCopy().put("catalogVersion",catalog);ObjectNode doc=JSON.createObjectNode();doc.set("initialDefinition",def);store("INITIAL_DRAFT",doc);workbench.open();}
    private void open(){page().locator("#open-authoring").click();page().locator("#confirm-authoring").click();workbench.awaitText("Saved school-definition draft");}
    private void nav(String section){page().locator("button[data-section='"+section+"']").click();}
    private com.microsoft.playwright.Page page(){return workbench.page();}
    private JsonNode draft(){return storedWorkspaceDocument().path("definitionDraft");}
    private JsonNode definition(){return draft().path("definition");}
    private ObjectNode request(){return JSON.createObjectNode().put("targetCatalog",9);}
    private JsonNode preview(){APIResponse response=command("catalog/preview",request(),null);assertEquals(200,response.status());return JSON.readTree(response.text());}
    private APIResponse save(JsonNode preview,String version){ObjectNode body=JSON.createObjectNode();body.set("request",request());body.set("token",preview.path("token"));return command("catalog",body,version);}
    private String base(){return "http://localhost:"+port;}
    private APIResponse command(String route,JsonNode body,String version){JsonNode csrf=JSON.readTree(page().request().get(base()+"/api/csrf").text());return page().request().post(base()+"/api/definition-draft/"+route,RequestOptions.create().setData(JSON.writeValueAsString(body)).setHeader("Content-Type","application/json").setHeader("Origin",base()).setHeader("If-Match",version==null?"\"ws-"+storedVersion()+"\"":version).setHeader(csrf.path("headerName").asString(),csrf.path("token").asString()));}
    private void store(String state,JsonNode document){jdbc.sql("UPDATE workspace_aggregate SET lifecycle_state=:state,version=version+1,active_run_id=NULL,document=CAST(:document AS jsonb) WHERE workspace_id=1").param("state",state).param("document",JSON.writeValueAsString(document)).update();}
}
